<script setup>
import {defineAsyncComponent,onMounted,onUnmounted,ref} from 'vue'
import PageHeader from '../components/PageHeader.vue'
const OperationalTrends=defineAsyncComponent(()=>import('../components/OperationalTrends.vue'))
const DashboardChart=defineAsyncComponent(()=>import('../components/DashboardChart.vue'))
import EnterpriseDashboard from '../components/EnterpriseDashboard.vue'
import {api} from '../services/api.js'
const stats=ref(null),events=ref([]),deniedPorts=ref([]),error=ref(''),trafficError=ref(''),trafficLoading=ref(true)
const controller=new AbortController()
const options={signal:controller.signal}
onMounted(()=>{
  api('/reports/dashboard?section=summary',options).then(value=>{stats.value=value}).catch(cause=>{if(cause.name!=='AbortError')error.value=cause.message})
  api('/reports/dashboard?section=traffic',options).then(value=>{deniedPorts.value=value.deniedPorts}).catch(cause=>{if(cause.name!=='AbortError')trafficError.value=cause.message}).finally(()=>{trafficLoading.value=false})
  api('/logs/search?pageSize=6&pagination=cursor&includeTotal=false',options).then(value=>{events.value=value.items}).catch(cause=>{if(cause.name!=='AbortError')error.value=cause.message})
})
onUnmounted(()=>controller.abort())
</script>
<template><div class="view dashboard-view"><h1 class="sr-only">Fleet overview</h1><PageHeader eyebrow="COMMAND CENTER / OVERVIEW" title="Fleet overview" description="Operational status across your Windows firewall estate"><router-link to="/inventory" class="button secondary"><i class="mdi mdi-plus"></i> Add node</router-link><router-link to="/policies" class="button primary"><i class="mdi mdi-source-branch"></i> Policy studio</router-link></PageHeader><div v-if="error" class="error-msg">{{error}}</div><div v-if="!stats&&!error" role="status" class="empty-table">Loading fleet overview…</div><template v-if="stats"><EnterpriseDashboard :stats="stats" :coverage-summary="stats.coverageSummary"/><div class="metric-grid hacker-dashboard"><div class="metric glass"><div class="metric-top"><span>MANAGED NODES</span><i class="mdi mdi-server-network"></i></div><strong>{{stats.totalNodes}}</strong><small><span class="online-dot"></span> {{stats.reachableNodes}} reachable · {{stats.agentsOnline}} agents online / {{stats.agentsOffline}} offline</small></div><div class="metric glass"><div class="metric-top"><span>ACTIVE POLICIES</span><i class="mdi mdi-shield-check-outline"></i></div><strong>{{stats.policies}}</strong><small>{{stats.compliantNodes}} compliant nodes · {{stats.fleetCompliancePct===null?'—':`${stats.fleetCompliancePct}%`}} fleet compliance</small></div><div class="metric glass"><div class="metric-top"><span>VERIFIER PASS RATE</span><i class="mdi mdi-check-decagram-outline"></i></div><strong>{{stats.verifierPassRate??'—'}}<span v-if="stats.verifierPassRate!==null">%</span></strong><small>{{stats.verifierInconclusive}} inconclusive checks</small></div><div class="metric glass"><div class="metric-top"><span>FAILED APPLIES</span><i class="mdi mdi-alert-circle-outline"></i></div><strong :class="{'danger-text':stats.failedApplies}">{{stats.failedApplies}}</strong><small>Review apply history</small></div></div><div class="dashboard-grid hacker-dashboard"><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">POSTURE</span><h2>Fleet coverage</h2></div><router-link to="/reports">VIEW REPORT <i class="mdi mdi-arrow-right"></i></router-link></div><div class="coverage-content"><div class="chart-box"><DashboardChart kind="coverage" :coverage-summary="stats.coverageSummary" /></div><div class="coverage-list"><div><span class="legend-dot green"></span> Protected nodes <strong>{{stats.coverageSummary.assigned}}</strong></div><div><span class="legend-dot gray"></span> Missing policy <strong>{{stats.coverageSummary.uncovered}}</strong></div><div><span class="legend-dot red"></span> Observed drift <strong>{{stats.coverageSummary.drift}}</strong></div></div></div></section><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">TELEMETRY</span><h2>Top denied ports</h2></div><router-link to="/logs">EXPLORE LOGS <i class="mdi mdi-arrow-right"></i></router-link></div><div class="chart-box bar"><div v-if="trafficLoading" role="status" class="empty-chart">Loading traffic totals…</div><div v-else-if="trafficError" class="error-msg">{{trafficError}}</div><DashboardChart v-else-if="deniedPorts.length" kind="denied" :denied-ports="deniedPorts" /><div v-else class="empty-chart"><i class="mdi mdi-chart-bar"></i><span>No denied traffic has been collected yet</span></div></div></section></div><OperationalTrends :stats="stats"/><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">LATEST ACTIVITY</span><h2>Recent security events</h2></div><router-link to="/logs">ALL EVENTS <i class="mdi mdi-arrow-right"></i></router-link></div><div class="table-wrap"><table><thead><tr><th>TIME</th><th>NODE</th><th>ACTION</th><th>SOURCE</th><th>DESTINATION</th><th>PORT</th></tr></thead><tbody><tr v-for="event in events.slice(0,6)" :key="event.id"><td>{{new Date(event.received_at).toLocaleString()}}</td><td class="mono">{{event.node_id?.slice(0,8)}}</td><td><span class="status" :class="event.action">{{event.action}}</span></td><td class="mono">{{event.src_ip||'—'}}</td><td class="mono">{{event.dst_ip||'—'}}</td><td class="mono">{{event.dst_port||'—'}}</td></tr><tr v-if="!events.length"><td colspan="6" class="empty-table">No events yet. Configure log collection on a node to begin.</td></tr></tbody></table></div></section></template></div></template>
